def build_people():
    # All times in 24-hour format strings, converted to minutes
    people = [
        {"name": "Karen", "location": "Haight-Ashbury", "start": to_min("21:00"), "end": to_min("21:45"), "min": 45},
        {"name": "Jessica", "location": "Nob Hill", "start": to_min("13:45"), "end": to_min("21:00"), "min": 90},
        {"name": "Brian", "location": "Russian Hill", "start": to_min("15:30"), "end": to_min("21:45"), "min": 60},
        {"name": "Kenneth", "location": "North Beach", "start": to_min("9:45"), "end": to_min("21:00"), "min": 30},
        {"name": "Jason", "location": "Chinatown", "start": to_min("8:15"), "end": to_min("11:45"), "min": 75},
        {"name": "Stephanie", "location": "Union Square", "start": to_min("14:45"), "end": to_min("18:45"), "min": 105},
        {"name": "Kimberly", "location": "Embarcadero", "start": to_min("9:45"), "end": to_min("19:30"), "min": 75},
        {"name": "Steven", "location": "Financial District", "start": to_min("7:15"), "end": to_min("21:15"), "min": 60},
        {"name": "Mark", "location": "Marina District", "start": to_min("10:15"), "end": to_min("13:00"), "min": 75},
    ]
    return people

def plan_schedule():
    travel = build_travel()
    people = build_people()
    n = len(people)
    start_loc = "Presidio"
    start_time = to_min("9:00")

    # Precompute for speed
    loc_of = [p["location"] for p in people]
    start_of = [p["start"] for p in people]
    end_of = [p["end"] for p in people]
    min_of = [p["min"] for p in people]
    name_of = [p["name"] for p in people]

    # Order indices to try promising candidates earlier (by earliest end time)
    indices = list(range(n))

    # Memoization: key -> (best_count, best_endtime, best_travel, itinerary)
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dfs(cur_loc, cur_time, visited_mask):
        best = (0, cur_time, 0, [])  # count, end_time, total_travel, itinerary
        # Try each not yet visited
        for i in indices:
            if visited_mask & (1 << i):
                continue
            # Travel time
            t = travel[cur_loc][loc_of[i]]
            arrival = cur_time + t
            start = max(arrival, start_of[i])
            end = start + min_of[i]
            if end <= end_of[i]:
                # Feasible to meet i
                sub_count, sub_end, sub_travel, sub_itin = dfs(loc_of[i], end, visited_mask | (1 << i))
                total_count = 1 + sub_count
                total_end = sub_end
                total_travel = t + sub_travel
                itinerary = [{
                    "action": "meet",
                    "location": loc_of[i],
                    "person": name_of[i],
                    "start_time": to_str(start),
                    "end_time": to_str(end)
                }] + sub_itin
                # Choose best: maximize count; tie-break by earliest end; then minimal travel
                if (total_count > best[0] or
                    (total_count == best[0] and total_end < best[1]) or
                    (total_count == best[0] and total_end == best[1] and total_travel < best[2])):
                    best = (total_count, total_end, total_travel, itinerary)
        return best

    best_count, best_end, best_travel, best_itin = dfs(start_loc, start_time, 0)

    return {"itinerary": best_itin}

if __name__ == "__main__":
    result = plan_schedule()
    print(json.dumps(result, ensure_ascii=False))
